  // /* Theme variables */
  // :root {
  //   --primary: ${n?"#121212":"#FCFCFC"};
  //   --secondary: ${n?"#FCFCFC":"#121212"};
  //   --text-color: ${n?"#DAFAF4":"#121212"};
